DROP TABLE IF EXISTS `classroom_posts`;
CREATE TABLE `classroom_posts`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `external_post_id` bigint NULL DEFAULT NULL COMMENT 'ID bài đăng trong classroom-service',
  `classroom_id` bigint NOT NULL COMMENT 'ID lớp học',
  `classroom_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Mã lớp học',
  `author_id` bigint NOT NULL COMMENT 'ID người tạo bài đăng',
  `author_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tên người tạo bài đăng',
  `teacher_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Tên giáo viên quản lý lớp',
  `post_type` enum('ANNOUNCEMENT','ASSIGNMENT','TEST') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ANNOUNCEMENT' COMMENT 'Loại bài đăng',
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Tiêu đề bài đăng',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Nội dung bài đăng',
  `attempt_limit` int NULL DEFAULT NULL COMMENT 'Số lần làm bài',
  `question_count` int NULL DEFAULT NULL COMMENT 'Số câu hỏi',
  `max_points` int NULL DEFAULT NULL COMMENT 'Điểm tối đa',
  `start_at` datetime NULL DEFAULT NULL COMMENT 'Thời gian bắt đầu bài tập/bài kiểm tra',
  `duration_minutes` int NULL DEFAULT NULL COMMENT 'Thời lượng (phút)',
  `reference_test_id` bigint NULL DEFAULT NULL COMMENT 'ID bài kiểm tra tham chiếu',
  `reference_test_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Tên bài kiểm tra tham chiếu',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'Thời gian tạo bài đăng',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP COMMENT 'Thời gian cập nhật cuối cùng',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_classroom_id`(`classroom_id` ASC) USING BTREE,
  INDEX `idx_external_post_id`(`external_post_id` ASC) USING BTREE,
  INDEX `idx_author_id`(`author_id` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_post_type`(`post_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Lưu dữ liệu bài đăng lớp học để đồng bộ với classroom-service' ROW_FORMAT = Dynamic;

