  `created_at` datetime(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_test_id`(`test_id` ASC) USING BTREE,
  INDEX `idx_order_index`(`order_index` ASC) USING BTREE,
