  INDEX `idx_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_test_name`(`name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 88 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Table storing test information' ROW_FORMAT = Dynamic;

